// Package domain holds entities and rules. It imports only the standard library.
package domain

// IDs are ULIDs (26 characters), generated by the application, never the database.
type (
	// ChurchID identifies a church.
	ChurchID string
	// UserID identifies a user.
	UserID string
	// MembershipID identifies a user's membership in a church.
	MembershipID string
	// RoleID identifies a church's role.
	RoleID string
	// InviteID identifies an invite.
	InviteID string
	// TranslationID identifies a Bible translation.
	TranslationID string
	// SongID identifies a song of a church (06).
	SongID string
	// SectionID identifies one section (verse, chorus …) of a song.
	SectionID string
	// SongGroupID identifies the group that links the language versions of a hymn.
	SongGroupID string
	// ReadingID identifies a stored reading of a church (07).
	ReadingID string
	// ImportBatchID identifies an import batch (08).
	ImportBatchID string
	// ImportCandidateID identifies one candidate song of an import batch.
	ImportCandidateID string
	// DutyID identifies a duty of a church (09).
	DutyID string
	// SingingPartID identifies a singing part of a church (09).
	SingingPartID string
	// TemplateID identifies a liturgy template (09).
	TemplateID string
	// ServiceID identifies a regular service (09).
	ServiceID string
	// LiturgyID identifies a liturgy (10).
	LiturgyID string
	// ItemID identifies an item of a liturgy.
	ItemID string
	// ItemSongID identifies one song in a song item.
	ItemSongID string
	// EntryID identifies one entry of a song's sequence in a liturgy.
	EntryID string
	// AssignmentID identifies the assignment of a person to a duty.
	AssignmentID string
	// EditID identifies one row of a liturgy's history.
	EditID string
)
